CREATE TABLE stories(id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id)) STRICT;
CREATE TABLE story_revisions(id TEXT PRIMARY KEY, story_id TEXT NOT NULL REFERENCES stories(id), revision INTEGER NOT NULL, title TEXT NOT NULL, markdown TEXT NOT NULL, source_ref TEXT NOT NULL, context_json TEXT NOT NULL CHECK(json_valid(context_json)), created_at INTEGER NOT NULL, UNIQUE(story_id,revision)) STRICT;
CREATE TABLE requirements(id TEXT PRIMARY KEY, story_revision_id TEXT NOT NULL REFERENCES story_revisions(id), criterion_key TEXT NOT NULL, text TEXT NOT NULL, source_ref TEXT NOT NULL, origin TEXT NOT NULL CHECK(origin IN ('specified','ai-inferred')), UNIQUE(story_revision_id,criterion_key)) STRICT;
CREATE TABLE requirement_approvals(id TEXT PRIMARY KEY, requirement_id TEXT NOT NULL REFERENCES requirements(id), reviewer TEXT NOT NULL, approved_at INTEGER NOT NULL) STRICT;
CREATE TABLE plans(id TEXT PRIMARY KEY, story_id TEXT NOT NULL REFERENCES stories(id)) STRICT;
CREATE TABLE plan_revisions(id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES plans(id), revision INTEGER NOT NULL, story_revision_id TEXT NOT NULL REFERENCES story_revisions(id), proposal_json TEXT NOT NULL CHECK(json_valid(proposal_json)), policy_json TEXT NOT NULL CHECK(json_valid(policy_json)), content_hash TEXT NOT NULL, provider_json TEXT NOT NULL CHECK(json_valid(provider_json)), created_at INTEGER NOT NULL, UNIQUE(plan_id,revision)) STRICT;
CREATE TABLE plan_approvals(id TEXT PRIMARY KEY, plan_revision_id TEXT NOT NULL UNIQUE REFERENCES plan_revisions(id), content_hash TEXT NOT NULL, reviewer TEXT NOT NULL, approved_at INTEGER NOT NULL) STRICT;
CREATE TABLE test_runs(id TEXT PRIMARY KEY, plan_revision_id TEXT NOT NULL REFERENCES plan_revisions(id), status TEXT NOT NULL CHECK(status IN ('running','complete','cancelled','interrupted')), started_at INTEGER NOT NULL, finished_at INTEGER, selected_json TEXT NOT NULL CHECK(json_valid(selected_json))) STRICT;
CREATE TABLE test_scenario_results(run_id TEXT NOT NULL REFERENCES test_runs(id), scenario_id TEXT NOT NULL, role_id TEXT NOT NULL REFERENCES role_profiles(id), status TEXT NOT NULL CHECK(status IN ('PASS','FAIL','BLOCKED','INCONCLUSIVE','FLAKY','NOT RUN')), PRIMARY KEY(run_id,scenario_id)) STRICT;
CREATE TABLE test_attempts(id TEXT PRIMARY KEY, run_id TEXT NOT NULL, scenario_id TEXT NOT NULL, attempt INTEGER NOT NULL, result_json TEXT NOT NULL CHECK(json_valid(result_json)), FOREIGN KEY(run_id,scenario_id) REFERENCES test_scenario_results(run_id,scenario_id), UNIQUE(run_id,scenario_id,attempt)) STRICT;
CREATE TABLE assertion_results(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES test_runs(id), scenario_id TEXT NOT NULL, attempt INTEGER NOT NULL, assertion_key TEXT NOT NULL, requirement_id TEXT NOT NULL REFERENCES requirements(id), status TEXT NOT NULL CHECK(status IN ('PASS','FAIL','INCONCLUSIVE')), expected_json TEXT NOT NULL, actual_json TEXT NOT NULL, evidence_id TEXT NOT NULL REFERENCES artifacts(id)) STRICT;
CREATE TABLE fixture_reservations(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES test_runs(id), scenario_id TEXT NOT NULL, attempt INTEGER NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('unique-email','duplicate-email')), status TEXT NOT NULL CHECK(status IN ('reserved','created','cleaned','orphan')), message TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE qa_jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('plan','execute')), status TEXT NOT NULL CHECK(status IN ('running','complete','failed','cancelled','interrupted')), reference_id TEXT NOT NULL, result_id TEXT, message TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL) STRICT;
CREATE INDEX plan_revisions_story ON plan_revisions(story_revision_id);
CREATE INDEX test_runs_plan ON test_runs(plan_revision_id,started_at);
CREATE TRIGGER story_revisions_no_update BEFORE UPDATE ON story_revisions BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER story_revisions_no_delete BEFORE DELETE ON story_revisions BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER requirements_no_update BEFORE UPDATE ON requirements BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER requirements_no_delete BEFORE DELETE ON requirements BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER plan_revisions_no_update BEFORE UPDATE ON plan_revisions BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER plan_revisions_no_delete BEFORE DELETE ON plan_revisions BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER plan_approvals_no_update BEFORE UPDATE ON plan_approvals BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER plan_approvals_no_delete BEFORE DELETE ON plan_approvals BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER requirement_approvals_no_update BEFORE UPDATE ON requirement_approvals BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER requirement_approvals_no_delete BEFORE DELETE ON requirement_approvals BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER test_attempts_no_update BEFORE UPDATE ON test_attempts BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER test_attempts_no_delete BEFORE DELETE ON test_attempts BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER assertion_results_no_update BEFORE UPDATE ON assertion_results BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
CREATE TRIGGER assertion_results_no_delete BEFORE DELETE ON assertion_results BEGIN SELECT RAISE(ABORT, 'Immutable history'); END;
